const BY_ID = new Map(FIELD_CATALOGUE.map((f) => [f.id, f]));

/** Throws on an unknown id — a column may not name a field the source list lacks. */
export function catalogueField(id: string): CatalogueField {
  const f = BY_ID.get(id);
  if (!f) throw new Error(`Unknown catalogue field id: "${id}"`);
  return f;
}
